-- Shared by every agent: write its own audit entries, nothing else.
grant usage on schema counsel to counsel_agents;
grant insert (run_id, action, target, decision, detail) on counsel.audit_log to counsel_agents;

-- The runtime logs in, holds no privileges itself (NOINHERIT), and must
-- SET ROLE to one agent per step. Its password is set at deploy time.
do $$
begin
  if not exists (select from pg_roles where rolname = 'counsel_runtime') then
    create role counsel_runtime login noinherit;
  end if;
end $$;
alter role counsel_runtime noinherit nocreatedb nocreaterole nobypassrls;

